sys_variable_value.value:
(function execute(inputs, outputs) {
    try {
        var executionSysId = inputs.ai_data_execution ? inputs.ai_data_execution.sys_id + '' : '';
        var result = new x_agiro_ai_disc_cl.ClaudeDiscoveryUtil().discoverAndLoad(executionSysId);
        outputs.error_message = result.error_message;
    } catch (e) {
        outputs.error_message = 'Claude discovery failed: ' + e.message;
    }
})(inputs, outputs);

